  d['aliasWriteCheck']={'isDirectWriter':writes,'destinationIsAlias':None if writes else False,'adoptsAliasAsNewDestination':False,'evidence':'No writer destination is rewritten in this turn. A variable/external writer target requires the named bounded export before its candidate can be accepted; no alias safety is inferred from an unchanged path spelling.'}
